% Feature extraction: first differentiator -> second differentiator -> counter -> NN.
% Same script structure as your attachment: parameters, named concentration
% arrays, one main for loop, plots, and small helpers at the end.
%
% Each differentiator has three core reactions:
%   r11: X1 -> M1; r12: M1 -> Y1; r13: X1 + Y1 -> products.
%   r21: Y1 -> M2; r22: M2 -> Y2; r23: Y1 + Y2 -> products.
% X1=m_in is an imposed/buffered input. M1/M2 are memory concentrations;
% Y1/Y2 are physical outputs. Cross-block names: m_d, m_d2, m_c, m_out.
% With consuming coupling, BOTH r21 and r23 withdraw Y1.
%
% Concentrations and Km: mM; Vmax: mM/s; kcat: 1/s; time: s.
% The product of two MM fractions is an assumed two-substrate rate law;
% its applicability must be checked for the chosen enzyme mechanism.
% Km and enzyme values below are calibration trials, not validated mappings.
% Shared input Km in production/removal gives local adaptive behavior.
% This motif estimates relative decline outside a narrow operating range.
% Both stages invert: Y1 rises as falling-slope magnitude builds, and Y2
% dips as Y1 rises. The counter is inhibited by Y2 and activated by Y1.
% The counter remains a leaky analog accumulator; its Hill regulation is
% phenomenological. Digital reference curves are used only for plotting.
%
% Backward Euler is retained from the previous MM version. Reaction rates
% use n+1 concentrations so enzymatic removal cannot overdraw a pool.
% solve_mm_pool solves ONE concentration balance; fzero closes coupled
% balances just as in your original loop. No combined concentration vector.

clc;
clearvars;
close all;

% Including parent folders up to your project folder named 'code'.
addingPathParentFolderByName('code'); %[output:96d9d168]
Parameters
%%
%[text] ## Load sample data
load Dataset_cell2cell.mat
Dataset = rmmissing(Dataset);
dist = table2array(Dataset(:,1));
vesicles = table2array(Dataset(:,2:end));

row = 1;
gain_in = 1e-4;                     % mM/vesicle: 500 vesicles -> 0.05 mM
vesicleInput = vesicles(row,:).';
t = (0:numel(vesicleInput)-1)' * dt0;
dtInput = dt0;
m_in = gain_in * vesicleInput;
N = length(t);
u_ref = m_in(1);
assert(N >= 3 && all(isfinite(m_in)) && all(m_in > 0), ...
    'The adaptive model requires a finite, strictly positive input.');
slope = diff(vesicles,1,2)/dtInput;   % vesicles/s, plotting reference
[peak,loc] = min(slope,[],2);
peakTime = (loc-1)*dtInput;
%%
%[text] ## Parameters: differentiators
coupling_mode = 'consuming';         % 'consuming' or 'regulatory'
consume_interstage = strcmpi(coupling_mode,'consuming');
assert(consume_interstage || strcmpi(coupling_mode,'regulatory'), ...
    'Choose consuming or regulatory coupling.');
% Regulatory coupling is appropriate only for a verified nonconsuming
% catalytic/allosteric mechanism. The default includes chemical withdrawals.

tau_M1 = 30; tau_Y1 = 3;             % first-stage memory/relaxation [s]
tau_M2 = 10; tau_Y2 = 1;             % second-stage memory/relaxation [s]
Y1_ref = 1e-2;                      % design basal output [mM]
Y2_ref = 1e-6;                      % small output limits upstream loading

use_first_stage_activation = true;
n_gate1 = 4; n_gate2 = 8;
K_gate1 = Y1_ref; K_gate2 = Y2_ref;
gate_reference_rel_tol = 1e-6;       % digital diagnostic only

% Michaelis constants / calibration at the operating point

% These default Km values are DESIGN TRIALS, not BRENDA measurements.
% Ratios of 10 give moderate saturation while retaining the local response.
lambda_X1 = 10; lambda_M1 = 10; lambda_Y1 = 10;
lambda_X2 = 10; lambda_M2 = 10; lambda_Y2 = 10;
assert(all([lambda_X1,lambda_M1,lambda_Y1,lambda_X2,lambda_M2,lambda_Y2] > 0), ...
    'Michaelis-constant design ratios must be positive.');
gx2 = lambda_X2/(1+lambda_X2);
gm1 = lambda_M1/(1+lambda_M1); gm2 = lambda_M2/(1+lambda_M2);
gy1 = lambda_Y1/(1+lambda_Y1); gy2 = lambda_Y2/(1+lambda_Y2);
consume_interstage = strcmpi(coupling_mode,'consuming');
assert(consume_interstage || strcmpi(coupling_mode,'regulatory'), ...
    'coupling_mode must be consuming or regulatory.');

% Calibrate stage 2 first: J2 is its steady conversion/removal flux.
J2 = Y2_ref/(tau_Y2*gy2);
M2_ref = J2*tau_M2*gm2;
Km_21_Y = lambda_X2*Y1_ref; Km_22_M = lambda_M2*M2_ref;
Km_23_Y1 = Km_21_Y; Km_23_Y2 = lambda_Y2*Y2_ref;
V21_target = J2/mm_fraction(Y1_ref,Km_21_Y);
V22_target = J2/mm_fraction(M2_ref,Km_22_M);
V23_target = J2/(mm_fraction(Y1_ref,Km_23_Y1)*mm_fraction(Y2_ref,Km_23_Y2));

% Initial stage-2 load is 2*J2. Its instantaneous derivative with respect
% to Y1 is 2*J2*gx2/Y1_ref (holding M2 and Y2 fixed).
load_derivative = 2*consume_interstage*J2*gx2/Y1_ref;
clearance_derivative1 = 1/tau_Y1-load_derivative;
assert(clearance_derivative1 > 0, ...
    'Requested stage-1 relaxation is slower than its downstream load.');
J13 = clearance_derivative1*Y1_ref/gy1;
J11 = J13+2*consume_interstage*J2;
M1_ref = J11*tau_M1*gm1;
Km_11_X = lambda_X1*u_ref; Km_12_M = lambda_M1*M1_ref;
Km_13_X = Km_11_X; Km_13_Y = lambda_Y1*Y1_ref;
V11_target = J11/mm_fraction(u_ref,Km_11_X);
V12_target = J11/mm_fraction(M1_ref,Km_12_M);
V13_target = J13/(mm_fraction(u_ref,Km_13_X)*mm_fraction(Y1_ref,Km_13_Y));

% Illustrative turnover estimates only; no new EC mapping is asserted.
% SA: umol/(min*mg); MW: kDa; SA*MW/60 has units 1/s.
kcat_11 = 10^2.5*48.901/60; kcat_12 = kcat_11;
kcat_13 = 10^1.5*75/60;
kcat_21 = kcat_11; kcat_22 = kcat_12; kcat_23 = kcat_13;
% Design enzyme concentrations. Edit these six E values to study capacity.
% Initialization and linear references are recomputed from the actual rates.
E_11 = V11_target/kcat_11; E_12 = V12_target/kcat_12;
E_13 = V13_target/kcat_13;
E_21 = V21_target/kcat_21; E_22 = V22_target/kcat_22;
E_23 = V23_target/kcat_23;
V_11 = kcat_11*E_11; V_12 = kcat_12*E_12; V_13 = kcat_13*E_13;
V_21 = kcat_21*E_21; V_22 = kcat_22*E_22; V_23 = kcat_23*E_23;
assert(all(isfinite([V_11,V_12,V_13,V_21,V_22,V_23])) && ...
    all([V_11,V_12,V_13,V_21,V_22,V_23] > 0), ...
    'Enzyme capacities must be finite and positive.');
assert(Km_11_X == Km_13_X && Km_21_Y == Km_23_Y1, ...
    'This adaptive calibration requires shared input Km within each stage.');
reaction_parameters = table( ...
    {'r11';'r12';'r13';'r21';'r22';'r23'}, ...
    [Km_11_X;Km_12_M;Km_13_X;Km_21_Y;Km_22_M;Km_23_Y1], ...
    [NaN;NaN;Km_13_Y;NaN;NaN;Km_23_Y2], ...
    [kcat_11;kcat_12;kcat_13;kcat_21;kcat_22;kcat_23], ...
    [E_11;E_12;E_13;E_21;E_22;E_23], ...
    [V_11;V_12;V_13;V_21;V_22;V_23], ...
    'VariableNames',{'Reaction','Km_first_mM','Km_second_mM', ...
                     'kcat_per_s','Enzyme_mM','Vmax_mM_per_s'});
disp(reaction_parameters); %[output:1bcae6d5]
fprintf('Coupling: %s. Km and turnover defaults are calibration trials.\n',coupling_mode); %[output:30361d6f]

% -------- Counter: retained activity examples, corrected descriptions --------
% Legacy SA/MW examples below do not validate enzyme mappings for this design.
% Cp: buffered precursor -> C; gate controls active enzyme fraction.
E_Cp = 1e-3; SA_Cp = 10^0.5; MW_Cp = 75;
kcat_Cp = SA_Cp*MW_Cp/60;
V_Cp = kcat_Cp*E_Cp;
% Cr: regulated depletion of reset substrate Cs -> products.
E_Cr = 1e-3; SA_Cr = 10^1.5; MW_Cr = 75;
kcat_Cr = SA_Cr*MW_Cr/60;
V_Cr = kcat_Cr*E_Cr;
Km_Cr_Cs = 10^0.5;
% Cg: C + Cs -> products, clearing the accumulated concentration.
E_Cg = 1; SA_Cg = 10^1.5; MW_Cg = 275;
kcat_Cg = SA_Cg*MW_Cg/60;
V_Cg = kcat_Cg*E_Cg;
Km_Cg_c = 10^0.5;
Km_Cg_Cs = 10^0.5;
m_Cs_base = 0.01;
k_Cs_supply = 1;

% -------- Neural network: original Hill production / decay equations --------
V_Ni = 1; K_Ni = 0.1; n_Ni = 2;
V_Na = 1; K_Na = 0.1; n_Na = 2;
V_Nb = 1; K_Nb = 0.1; n_Nb = 2;
V_No = 1; K_No = 0.1; n_No = 2;
m_Nc_const = 1;
k_Ni_deg = 1; k_Na_deg = 1; k_Nb_deg = 1; k_out_deg = 1;
%%
%[text] ## Initial concentrations: equilibrium at the first input sample
%[text] Starting at equilibrium avoids a startup pulse unrelated to input slope.
root_options = optimset('Display','off','TolX',realmin);
assert(V_13 > V_11 && V_23 > V_21, ...
    'Adaptive removal capacities must exceed their source capacities.');
j1_base = V_11 * u_ref/(Km_11_X+u_ref);
assert(j1_base < V_12, 'No finite equilibrium for memory M1.');
M1_base = Km_12_M * j1_base/(V_12-j1_base);
Y1_isolated = Km_13_Y * V_11/(V_13-V_11);

if consume_interstage
    % Include the TWO stage-2 withdrawals at equilibrium.
    balance_initial_Y1 = @(z) V_13*u_ref/(Km_13_X+u_ref) * ...
        (Y1_isolated*z)/(Km_13_Y+Y1_isolated*z) + ...
        2*V_21*(Y1_isolated*z)/(Km_21_Y+Y1_isolated*z) - j1_base;
    fraction_initial_Y1 = fzero(balance_initial_Y1,[0 1],root_options);
    Y1_base = Y1_isolated * fraction_initial_Y1;
else
    Y1_base = Y1_isolated;
end
j2_base = V_21 * Y1_base/(Km_21_Y+Y1_base);
assert(j2_base < V_22, 'No finite equilibrium for memory M2.');
M2_base = Km_22_M * j2_base/(V_22-j2_base);
Y2_base = Km_23_Y2 * V_21/(V_23-V_21);

gate_base = 1-hill_activation(Y2_base,K_gate2,n_gate2);
if use_first_stage_activation
    gate_base = gate_base * hill_activation(Y1_base,K_gate1,n_gate1);
end
j_Cp_base = V_Cp * gate_base;
assert(j_Cp_base < k_Cs_supply*m_Cs_base, ...
    'Basal counter production exceeds reset-substrate supply.');
balance_initial_Cs = @(z) k_Cs_supply*(m_Cs_base-m_Cs_base*z) - ...
    V_Cr*gate_base*(m_Cs_base*z)/(Km_Cr_Cs+m_Cs_base*z) - j_Cp_base;
Cs_base = m_Cs_base*fzero(balance_initial_Cs,[0 1],root_options);
reset_capacity_base = V_Cg * Cs_base/(Km_Cg_Cs+Cs_base);
assert(j_Cp_base < reset_capacity_base, ...
    'Basal counter production exceeds reset capacity.');
counter_base = Km_Cg_c*j_Cp_base/(reset_capacity_base-j_Cp_base);
Ni_base = V_Ni*hill_activation(counter_base,K_Ni,n_Ni)/k_Ni_deg;
Na_base = V_Na*hill_activation(Ni_base,K_Na,n_Na)/k_Na_deg;
Nb_base = V_Nb*hill_activation(Ni_base,K_Nb,n_Nb)/k_Nb_deg;
out_base = V_No*hill_activation(m_Nc_const*(Na_base+Nb_base),K_No,n_No)/k_out_deg;

% Actual baselines are recomputed if you edit enzyme concentrations.
% K_gate1/K_gate2 stay at their specified design thresholds.
Y1_ref = Y1_base; Y2_ref = Y2_base;
%%
%[text] ## Concentration arrays
%[text] First differentiator
m_M1 = zeros(N,1); m_M1(1) = M1_base;
m_Y1 = zeros(N,1); m_Y1(1) = Y1_base;
m_d  = zeros(N,1); m_d(1)  = Y1_base;   % cross-block alias of Y1

% Second differentiator
m_M2 = zeros(N,1); m_M2(1) = M2_base;
m_Y2 = zeros(N,1); m_Y2(1) = Y2_base;
m_d2 = zeros(N,1); m_d2(1) = Y2_base;   % cross-block alias of Y2

% Counter
m_c = zeros(N,1);  m_c(1) = counter_base;
m_Cs = zeros(N,1); m_Cs(1) = Cs_base;

% Neural network
m_Ni = zeros(N,1);  m_Ni(1) = Ni_base;
m_Na = zeros(N,1);  m_Na(1) = Na_base;
m_Nb = zeros(N,1);  m_Nb(1) = Nb_base;
m_out = zeros(N,1); m_out(1) = out_base;

% Reaction-rate arrays, for inspecting each reaction [mM/s]
v_11 = zeros(N,1); v_12 = zeros(N,1); v_13 = zeros(N,1);
v_21 = zeros(N,1); v_22 = zeros(N,1); v_23 = zeros(N,1);
v_11(1) = j1_base; v_12(1) = j1_base;
v_13(1) = V_13*u_ref/(Km_13_X+u_ref)*Y1_base/(Km_13_Y+Y1_base);
v_21(1) = j2_base; v_22(1) = j2_base; v_23(1) = j2_base;
v_Cp_arr = zeros(N,1); v_Cr_arr = zeros(N,1); v_Cg_arr = zeros(N,1);
v_Cp_arr(1) = j_Cp_base;
v_Cr_arr(1) = V_Cr*gate_base*Cs_base/(Km_Cr_Cs+Cs_base);
v_Cg_arr(1) = j_Cp_base;
enzyme_active = zeros(N,1); enzyme_active(1) = gate_base;
%%
%[text] ## Linear reference parameters: plotting only
%[text] These are derivatives of the MM rates at the initial equilibrium. Their separate reference arrays never enter a chemical reaction rate.
d11 = V_11*Km_11_X/(Km_11_X+u_ref)^2;
d12 = V_12*Km_12_M/(Km_12_M+M1_base)^2;
d13_X = V_13*Y1_base/(Km_13_Y+Y1_base)*Km_13_X/(Km_13_X+u_ref)^2;
d13_Y = V_13*u_ref/(Km_13_X+u_ref)*Km_13_Y/(Km_13_Y+Y1_base)^2;
d21 = V_21*Km_21_Y/(Km_21_Y+Y1_base)^2;
d22 = V_22*Km_22_M/(Km_22_M+M2_base)^2;
d23_Y1 = V_23*Y2_base/(Km_23_Y2+Y2_base)*Km_23_Y1/(Km_23_Y1+Y1_base)^2;
d23_Y2 = V_23*Y1_base/(Km_23_Y1+Y1_base)*Km_23_Y2/(Km_23_Y2+Y2_base)^2;
m_M1_ref = zeros(N,1); m_Y1_ref = zeros(N,1);
m_M2_ref = zeros(N,1); m_Y2_ref = zeros(N,1);
%%
%[text] ## Discrete-time simulation
for n = 1:N-1

    dt0 = t(n+1)-t(n);

    % ============================================================
    % FIRST CHEMICAL DIFFERENTIATOR
    % ============================================================
    % r11: input -> memory M1
    v_11(n+1) = V_11*m_in(n+1)/(Km_11_X+m_in(n+1));

    % r12: M1 -> Y1. Solve M1new + dt*v12(M1new) = available_M1.
    available_M1 = m_M1(n)+dt0*v_11(n+1);
    m_M1(n+1) = solve_mm_pool(available_M1,dt0,V_12,Km_12_M);
    v_12(n+1) = V_12*m_M1(n+1)/(Km_12_M+m_M1(n+1));

    % r13 removes Y1; r21 and r23 ALSO remove Y1 in consuming mode.
    available_Y1 = m_Y1(n)+dt0*v_12(n+1);
    capacity_13 = V_13*m_in(n+1)/(Km_13_X+m_in(n+1));
    rate_13 = @(y1) capacity_13*y1/(Km_13_Y+y1);

    % ============================================================
    % SECOND CHEMICAL DIFFERENTIATOR: coupled to Y1
    % ============================================================
    % Define the second-stage balances for a trial Y1 concentration.
    % They must be included before solving Y1 because both stages consume Y1.
    M2_previous = m_M2(n);
    Y2_previous = m_Y2(n);
    rate_21 = @(y1) V_21*y1/(Km_21_Y+y1);
    memory_2 = @(y1) solve_mm_pool( ...
        M2_previous+dt0*rate_21(y1),dt0,V_22,Km_22_M);
    rate_22 = @(y1) V_22*memory_2(y1)/(Km_22_M+memory_2(y1));
    capacity_23 = @(y1) V_23*y1/(Km_23_Y1+y1);
    output_2 = @(y1) solve_mm_pool( ...
        Y2_previous+dt0*rate_22(y1),dt0,capacity_23(y1),Km_23_Y2);
    rate_23 = @(y1) capacity_23(y1)*output_2(y1)/(Km_23_Y2+output_2(y1));

    if consume_interstage
        % z is the fraction of available Y1 remaining after consumption.
        % Y1new + dt*(v13 + v21 + v23) = available_Y1.
        if available_Y1 > 0
            balance1 = @(z) z+dt0/available_Y1 * ...
                (rate_13(available_Y1*z) + rate_21(available_Y1*z) + ...
                 rate_23(available_Y1*z)) - 1;
            fraction1 = fzero(balance1,[0 1],root_options);
            m_Y1(n+1) = available_Y1*fraction1;
        else
            m_Y1(n+1) = 0;
        end
    else
        m_Y1(n+1) = solve_mm_pool(available_Y1,dt0,capacity_13,Km_13_Y);
    end

    % Now advance the second-stage concentrations with the solved Y1.
    m_M2(n+1) = memory_2(m_Y1(n+1));
    m_Y2(n+1) = output_2(m_Y1(n+1));

    % Actual MM reaction rates at the updated concentrations.
    v_13(n+1) = V_13*m_in(n+1)/(Km_13_X+m_in(n+1)) * ...
        m_Y1(n+1)/(Km_13_Y+m_Y1(n+1));
    v_21(n+1) = V_21*m_Y1(n+1)/(Km_21_Y+m_Y1(n+1));
    v_22(n+1) = V_22*m_M2(n+1)/(Km_22_M+m_M2(n+1));
    v_23(n+1) = V_23*m_Y1(n+1)/(Km_23_Y1+m_Y1(n+1)) * ...
        m_Y2(n+1)/(Km_23_Y2+m_Y2(n+1));

    % The balances solved above are:
    % M1new = M1old + dt*(v11-v12)
    % Y1new = Y1old + dt*(v12-v13-consume_interstage*(v21+v23))
    % M2new = M2old + dt*(v21-v22)
    % Y2new = Y2old + dt*(v22-v23)
    m_d(n+1) = m_Y1(n+1);
    m_d2(n+1) = m_Y2(n+1);

    % ============================================================
    % COUNTER
    % ============================================================
    % Y2 inhibits production; Y1 optionally activates it.
    active_fraction = 1-hill_activation(m_d2(n+1),K_gate2,n_gate2);
    if use_first_stage_activation
        active_fraction = active_fraction * ...
            hill_activation(m_d(n+1),K_gate1,n_gate1);
    end
    enzyme_active(n+1) = active_fraction;

    % rCp: buffered precursor -> C
    v_Cp = V_Cp*active_fraction;
    available_c = m_c(n)+dt0*v_Cp;
    available_Cs = m_Cs(n)+dt0*k_Cs_supply*m_Cs_base;
    upper_Cs = available_Cs/(1+dt0*k_Cs_supply);

    % rCr depletes Cs; rCg consumes BOTH C and Cs with the SAME flux.
    % Solve the coupled implicit balances using a trial Cs concentration.
    counter_at_Cs = @(cs) solve_mm_pool(available_c,dt0, ...
        V_Cg*cs/(Km_Cg_Cs+cs),Km_Cg_c);
    rate_Cr = @(cs) V_Cr*active_fraction*cs/(Km_Cr_Cs+cs);
    rate_Cg = @(cs) V_Cg*cs/(Km_Cg_Cs+cs) * ...
        counter_at_Cs(cs)/(Km_Cg_c+counter_at_Cs(cs));
    if available_Cs > 0
        balance_Cs = @(z) z+dt0/available_Cs * ...
            (rate_Cr(upper_Cs*z)+rate_Cg(upper_Cs*z))-1;
        fraction_Cs = fzero(balance_Cs,[0 1],root_options);
        m_Cs(n+1) = upper_Cs*fraction_Cs;
    else
        m_Cs(n+1) = 0;
    end
    m_c(n+1) = counter_at_Cs(m_Cs(n+1));

    v_Cr = V_Cr*active_fraction*m_Cs(n+1)/(Km_Cr_Cs+m_Cs(n+1));
    v_Cg = V_Cg*m_c(n+1)/(Km_Cg_c+m_c(n+1)) * ...
        m_Cs(n+1)/(Km_Cg_Cs+m_Cs(n+1));
    % cnew  = cold  + dt*(vCp-vCg)
    % Csnew = Csold + dt*(k_Cs_supply*(m_Cs_base-Csnew)-vCr-vCg)
    v_Cp_arr(n+1) = v_Cp;
    v_Cr_arr(n+1) = v_Cr;
    v_Cg_arr(n+1) = v_Cg;

    % ============================================================
    % NEURAL NETWORK
    % ============================================================
    v_Ni = V_Ni*hill_activation(m_c(n+1),K_Ni,n_Ni);
    m_Ni(n+1) = (m_Ni(n)+dt0*v_Ni)/(1+dt0*k_Ni_deg);

    v_Na = V_Na*hill_activation(m_Ni(n+1),K_Na,n_Na);
    m_Na(n+1) = (m_Na(n)+dt0*v_Na)/(1+dt0*k_Na_deg);

    v_Nb = V_Nb*hill_activation(m_Ni(n+1),K_Nb,n_Nb);
    m_Nb(n+1) = (m_Nb(n)+dt0*v_Nb)/(1+dt0*k_Nb_deg);

    v_No = V_No*hill_activation(m_Nc_const*(m_Na(n+1)+m_Nb(n+1)),K_No,n_No);
    m_out(n+1) = (m_out(n)+dt0*v_No)/(1+dt0*k_out_deg);

    % ============================================================
    % LINEAR REFERENCES: for the existing comparison plots only
    % ============================================================
    % Solve the linearized coupled balances using named scalar quantities.
    % These arrays are deviations from equilibrium, not chemical species.
    input_deviation = m_in(n+1)-u_ref;
    m_M1_ref(n+1) = (m_M1_ref(n)+dt0*d11*input_deviation)/(1+dt0*d12);
    memory2_intercept = m_M2_ref(n)/(1+dt0*d22);
    memory2_coefficient = dt0*d21/(1+dt0*d22);
    output2_intercept = (m_Y2_ref(n)+dt0*d22*memory2_intercept)/(1+dt0*d23_Y2);
    output2_coefficient = (dt0*d22*memory2_coefficient-dt0*d23_Y1)/(1+dt0*d23_Y2);
    available_reference1 = m_Y1_ref(n)+dt0*d12*m_M1_ref(n+1) - ...
        dt0*d13_X*input_deviation;
    m_Y1_ref(n+1) = (available_reference1 - ...
        consume_interstage*dt0*d23_Y2*output2_intercept) / ...
        (1+dt0*(d13_Y+consume_interstage*(d21+d23_Y1)) + ...
         consume_interstage*dt0*d23_Y2*output2_coefficient);
    m_M2_ref(n+1) = memory2_intercept+memory2_coefficient*m_Y1_ref(n+1);
    m_Y2_ref(n+1) = output2_intercept+output2_coefficient*m_Y1_ref(n+1);
end
