%[text] ## Helpers
function x = solve_mm_pool(available,dt,V,Km)
    % Solve ONE implicit MM balance:
    % x + dt*V*x/(Km+x) = available.
    % Multiplying by Km+x gives
    % x^2 + (Km+dt*V-available)*x - Km*available = 0.
    % Use the positive quadratic root, evaluated without cancellation.
    if available == 0
        x = 0;
    elseif dt == 0 || V == 0
        x = available;
    else
        b = Km+dt*V-available;
        discriminant_root = hypot(b,2*sqrt(available)*sqrt(Km));
        if b >= 0
            x = available*(Km/(0.5*discriminant_root+0.5*b));
        else
            x = 0.5*discriminant_root-0.5*b;
        end
    end
end

function h = hill_activation(x,K,n)
    % Stable Hill fraction x^n/(K^n+x^n); zero input gives zero activation.
    h = 1./(1+exp(-n*log(x./K)));
end

function f = mm_fraction(x,Km)
    f = x./(Km+x);
end

function addingPathParentFolderByName(targetName)
    % Start from the current directory
    currFolder = pwd;
    found = false;
    
    % Continue searching until you reach the root folder
    while true
        % Get the parent folder
        [parentFolder, currentName] = fileparts(currFolder);
        
        % Check if the current folder's name is the target
        if strcmpi(currentName, targetName)
            found = true;
            break;
        end
        
        % If we've reached the root or no change, exit the loop
        if isempty(parentFolder) || strcmp(currFolder, parentFolder)
            break;
        end
        
        % Move one level up
        currFolder = parentFolder;
    end

    if found
        addpath(genpath(currFolder));
        fprintf('Adding matlab path to: %s\n', currFolder);
    else
        error('Folder named "%s" not found in any parent directory.', targetName);
    end
end

